"""Tests for depcycle.analyzer orchestrator."""

from __future__ import annotations

from pathlib import Path

import pytest

from depcycle.analyzer import analyze_project
from depcycle.config import AnalysisConfig
from depcycle.graph.node import NodeType


def test_analyze_project_full(tmp_path: Path) -> None:
    # Setup workspace directory
    ws_path = tmp_path / "myproj"
    ws_path.mkdir()

    # Create files:
    # pkg/mod_a.py: imports os, requests, .mod_b
    # pkg/mod_b.py: imports .mod_a
    pkg_dir = ws_path / "pkg"
    pkg_dir.mkdir()

    (pkg_dir / "__init__.py").write_text("", encoding="utf-8")
    (pkg_dir / "mod_a.py").write_text(
        "import os\nimport requests\nimport pkg.mod_b\nimport unknown_pkg\n",
        encoding="utf-8",
    )
    (pkg_dir / "mod_b.py").write_text(
        "import pkg.mod_a\n",
        encoding="utf-8",
    )

    (ws_path / "requirements.txt").write_text("requests\n", encoding="utf-8")

    config = AnalysisConfig(
        project_path=ws_path,
        show_third_party=True,
        show_stdlib=True,
        show_unknown=True,
    )

    graph, cycles = analyze_project(config)

    assert "pkg.mod_a" in graph.nodes
    assert "pkg.mod_b" in graph.nodes
    assert "os" in graph.nodes
    assert "requests" in graph.nodes
    assert "unknown_pkg" in graph.nodes

    assert graph.nodes["os"].node_type == NodeType.STDLIB
    assert graph.nodes["requests"].node_type == NodeType.THIRD_PARTY
    assert graph.nodes["unknown_pkg"].node_type == NodeType.UNKNOWN

    assert len(cycles) >= 1


def test_analyze_project_filter_nodes(tmp_path: Path) -> None:
    ws_path = tmp_path / "myproj"
    ws_path.mkdir()

    mod_a = ws_path / "mod_a.py"
    mod_a.write_text("import os\nimport requests\nimport unknown_pkg\n", encoding="utf-8")

    (ws_path / "requirements.txt").write_text("requests\n", encoding="utf-8")

    config = AnalysisConfig(
        project_path=ws_path,
        show_third_party=False,
        show_stdlib=False,
        show_unknown=False,
    )

    graph, cycles = analyze_project(config)

    assert "mod_a" in graph.nodes
    assert "os" not in graph.nodes
    assert "requests" not in graph.nodes
    assert "unknown_pkg" not in graph.nodes


def test_analyze_project_existing_node_and_empty_module(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    ws_path = tmp_path / "myproj"
    ws_path.mkdir()

    (ws_path / "mod_a.py").write_text("import sys\n", encoding="utf-8")

    from depcycle import utils
    original_path_to_mod = utils.path_to_module_name

    calls = 0

    def mock_path_to_module_name(file_path, root_path):
        nonlocal calls
        calls += 1
        # In second pass (building edges), return None for one call to trigger 'if not source_module: continue'
        if calls > 1:
            return None
        return original_path_to_mod(file_path, root_path)

    monkeypatch.setattr(utils, "path_to_module_name", mock_path_to_module_name)

    config = AnalysisConfig(project_path=ws_path)
    graph, cycles = analyze_project(config)
    assert "mod_a" in graph.nodes

